for name,folder in [('web',Path('/private/tmp/arm-video-demo/web-recording')),('desktop',Path('/private/tmp/arm-video-desktop/frames')),('android',Path('/private/tmp/arm-video-demo/android-recording'))]:
 d=json.loads((folder/'manifest.json').read_text());dest=raw/name;dest.mkdir(exist_ok=True)
 for item in d['frames']:shutil.copy2(folder/item['file'],dest/item['file'])
 (dest/'manifest.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
