chapters=[]
for code,kicker,title,bullets,seconds,source,note in rows:
 c=dict(code=code,kicker=kicker,title=title,bullets=bullets,duration=seconds,note=note)
 if source.startswith('old:'):c['image']=str(ROOT/'docs/management/presentation/screenshots'/source[4:]);c['source_type']='previous synthetic screenshot'
 elif source.startswith('probe:'):
  screen=raw/'screens';screen.mkdir(exist_ok=True);shutil.copy2(Path('/private/tmp/arm-video-demo')/source[6:],screen/source[6:]);c['image']=str(screen/source[6:]);c['source_type']='real isolated web page'
 elif source.startswith('diagram:'):c['diagram']=source[8:];c['source_type']='explanatory diagram; status in caption'
 else:
  name,a,b=source.split(':');c['sequence']={'folder':str(raw/name),'from':float(a),'to':float(b)};c['source_type']='real isolated application recording'
 chapters.append(c)
(OUT/'OVERVIEW_CHAPTERS.json').write_text(json.dumps(chapters,ensure_ascii=False,indent=2)+'\n')
print('OVERVIEW_PLANNED chapters='+str(len(chapters))+' seconds='+str(sum(c['duration'] for c in chapters)))
